74	    ```csharp
75	    [HttpGet("{id:guid}")]
76	    public async Task<ActionResult<OrderDto>> GetOrder(Guid id, CancellationToken ct = default)
77	    {
78	        var result = await orderService.GetOrderAsync(id, ct);
79	        return result is null ? NotFound() : MapToDto(result);
80	    }
