233	    import { CartService } from '../../../core/cart.service';
234	    import { OrderApiService } from '../order-api.service';
235	    import { OrderRejection } from '../order.model';
236	
237	    const REASON_TEXT: Record<string, string> = {
238	      unzulaessige_menge: 'unzulässige Menge',
239	      angebot_nicht_mehr_verfuegbar: 'Angebot nicht mehr verfügbar'
240	    };
241	
242	    @Component({
243	      selector: 'app-checkout-view',
244	      templateUrl: './checkout-view.html'
245	    })
246	    export class CheckoutView {
247	      private cartApi = inject(CartApiService);
248	      private orderApi = inject(OrderApiService);
249	      private cartService = inject(CartService);
250	      private router = inject(Router);
251	
252	      protected readonly cart = signal<Cart | null>(null);
253	      protected readonly loading = signal(true);
254	      protected readonly loadError = signal<string | null>(null);
255	
256	      protected readonly customerName = signal('');
257	      protected readonly deliveryAddress = signal('');
258	      protected readonly email = signal('');
259	      protected readonly submitting = signal(false);
260	      protected readonly submitError = signal<string | null>(null);
261	      protected readonly rejectionLines = signal<string[]>([]);
262	
263	      constructor() {
264	        this.cartApi.getCart(this.cartService.cartId()).subscribe({
265	          next: (cart) => {
266	            this.cart.set(cart);
267	            this.loading.set(false);
268	          },
269	          error: () => {
270	            this.loading.set(false);
271	            this.loadError.set('Warenkorb konnte nicht geladen werden.');
272	          }
273	        });
274	      }
275	
276	      private describeLine(productId: string, supplierId: string): string {
277	        const item = this.cart()?.items.find((i) => i.productId === productId && i.supplierId === supplierId);
278	        return item ? `${item.productName} (${item.supplierName})` : `${productId}/${supplierId}`;
279	      }
280	
281	      protected placeOrder(): void {
282	        if (this.submitting()) {
283	          return;
284	        }
285	
286	        const cartId = this.cartService.cartId();
287	        const name = this.customerName().trim();
288	        const address = this.deliveryAddress().trim();
289	        const mail = this.email().trim();
290	        if (!cartId || !name || !address || !mail) {
291	          this.submitError.set('Bitte Name, Lieferadresse und E-Mail-Adresse angeben.');
292	          return;
293	        }
294	
295	        this.submitting.set(true);
296	        this.submitError.set(null);
297	        this.rejectionLines.set([]);
298	
299	        this.orderApi.placeOrder(cartId, name, address, mail).subscribe({
300	          next: (order) => {
301	            this.router.navigate(['/orders', order.orderId]);
302	          },
303	          error: (err: HttpErrorResponse) => {
304	            this.submitting.set(false);
305	            if (err.status === 409) {
306	              const rejection = err.error as OrderRejection;
307	              this.submitError.set(rejection.error);
308	              this.rejectionLines.set(
309	                rejection.lines.map(
310	                  (l) => `${this.describeLine(l.productId, l.supplierId)}: ${REASON_TEXT[l.reason] ?? l.reason}`
311	                )
312	              );
313	            } else {
314	              this.submitError.set('Bestellung konnte nicht angelegt werden. Bitte Eingaben prüfen.');
315	            }
316	          }
317	        });
318	      }
319	    }
320	    ```
